// On-device unit tests for the KLAP crypto, using vectors generated by python-kasa 0.12
// (KlapTransportV2 + KlapEncryptionSession) with fixed seeds and credentials
// "user@example.com" / "hunter2".   Run:  pio test -e jc3636k518
#include <Arduino.h>
#include <unity.h>

#include <string.h>

// Compile the unit under test directly; test builds don't include src/ by default.
#include "../../src/tapo_klap.cpp"

static const uint8_t kAuthHash[32] = {0xb4, 0x9b, 0x2d, 0xa1, 0x6e, 0xe8, 0x15, 0x53, 0x35, 0xc9, 0x44, 0xa9, 0x08, 0xc0, 0x8f, 0xb4, 0xd1, 0x8e, 0xa9, 0x52, 0xca, 0x0f, 0x73, 0xb6, 0x0c, 0x8f, 0x77, 0xd0, 0x86, 0x42, 0xe7, 0x81};
