static const char kMsg[] = R"({"method":"get_device_info","request_time_milis":1,"terminal_uuid":"tapo-knob"})";
static const int32_t kSeq1 = 564099528;
static const uint8_t kEncrypted[112] = {0x8d, 0x1a, 0x46, 0x27, 0xd8, 0x8b, 0xfe, 0x01, 0x43, 0xd1, 0xff, 0x45, 0x06, 0xed, 0x00, 0x05, 0x3d, 0xbb, 0x43, 0x0e, 0x7d, 0x70, 0xf2, 0xde, 0x60, 0x4c, 0xef, 0x4f, 0x7f, 0xfb, 0xaa, 0x0b, 0xd6, 0x3d, 0x78, 0x8c, 0xb3, 0xaa, 0x0d, 0xd5, 0x50, 0x0d, 0xe4, 0x5f, 0xe9, 0x25, 0xfa, 0x7c, 0x75, 0x54, 0xeb, 0x3a, 0x2e, 0x31, 0xbc, 0x54, 0x73, 0xea, 0x26, 0x28, 0x20, 0x0a, 0x5b, 0xd8, 0x4b, 0xff, 0x5e, 0x3f, 0xde, 0x79, 0x7e, 0x6a, 0x3c, 0xed, 0x81, 0x6e, 0x88, 0x11, 0x01, 0xb8, 0x0b, 0x7a, 0x5a, 0xe5, 0x56, 0x7e, 0x31, 0x2c, 0xd0, 0x5a, 0xc9, 0x81, 0x49, 0x38, 0xdf, 0x65, 0x6e, 0x4d, 0x46, 0x82, 0xf2, 0xcb, 0xa5, 0xc9, 0xf9, 0x22, 0x7d, 0x3d, 0x59, 0x85, 0x89, 0x37};
