static const char kReplyPlain[] = R"({"error_code":0,"result":{"device_on":true,"brightness":42}})";

using namespace tapo;

void setUp() {}
void tearDown() {}

static void test_auth_hash() {
  uint8_t h[32];
  computeAuthHash("user@example.com", "hunter2", h);
  TEST_ASSERT_EQUAL_HEX8_ARRAY(kAuthHash, h, 32);
}

static void test_handshake_hashes() {
  uint8_t h[32];
  handshake1Hash(kLocalSeed, kRemoteSeed, kAuthHash, h);
  TEST_ASSERT_EQUAL_HEX8_ARRAY(kH1, h, 32);
  handshake2Hash(kLocalSeed, kRemoteSeed, kAuthHash, h);
  TEST_ASSERT_EQUAL_HEX8_ARRAY(kH2, h, 32);
}

static void test_session_derivation() {
  KlapCipher c;
  c.init(kLocalSeed, kRemoteSeed, kAuthHash);
  TEST_ASSERT_EQUAL_HEX8_ARRAY(kKey, c.key(), 16);
  TEST_ASSERT_EQUAL_INT32(kSeq0, c.seq());
}

static void test_encrypt_matches_python() {
  KlapCipher c;
  c.init(kLocalSeed, kRemoteSeed, kAuthHash);
  std::vector<uint8_t> out;
  const int32_t seq = c.encrypt(reinterpret_cast<const uint8_t *>(kMsg), strlen(kMsg), out);
  TEST_ASSERT_EQUAL_INT32(kSeq1, seq);
  TEST_ASSERT_EQUAL_size_t(sizeof(kEncrypted), out.size());
  TEST_ASSERT_EQUAL_HEX8_ARRAY(kEncrypted, out.data(), sizeof(kEncrypted));
}

static void test_decrypt_reply() {
  KlapCipher c;
  c.init(kLocalSeed, kRemoteSeed, kAuthHash);
  std::vector<uint8_t> out;
  c.encrypt(reinterpret_cast<const uint8_t *>(kMsg), strlen(kMsg), out);  // advances seq/IV
  std::string plain;
  TEST_ASSERT_TRUE(c.decrypt(kReply, sizeof(kReply), plain));
  TEST_ASSERT_EQUAL_STRING(kReplyPlain, plain.c_str());
}

static void test_decrypt_rejects_garbage() {
  KlapCipher c;
  c.init(kLocalSeed, kRemoteSeed, kAuthHash);
  uint8_t junk[64] = {};
  std::string plain;
  TEST_ASSERT_FALSE(c.decrypt(junk, 20, plain));  // too short
}

void setup() {
  delay(2000);  // let USB CDC enumerate
  UNITY_BEGIN();
  RUN_TEST(test_auth_hash);
  RUN_TEST(test_handshake_hashes);
  RUN_TEST(test_session_derivation);
  RUN_TEST(test_encrypt_matches_python);
  RUN_TEST(test_decrypt_reply);
  RUN_TEST(test_decrypt_rejects_garbage);
  UNITY_END();
}

void loop() {}
